import{_ as a,c as t,o as i,ae as r}from"./chunks/framework.CDAOyxyO.js";const g=JSON.parse('{"title":"Релизы","description":"","frontmatter":{},"headers":[],"relativePath":"projects/alt-domain/admc/releases/index.md","filePath":"projects/alt-domain/admc/releases/index.md"}'),e={name:"projects/alt-domain/admc/releases/index.md"};function o(n,l,h,p,s,u){return i(),t("div",null,l[0]||(l[0]=[r('<h1 id="релизы" tabindex="-1">Релизы <a class="header-anchor" href="#релизы" aria-label="Permalink to &quot;Релизы&quot;">​</a></h1><h2 id="_0-20-0-alt2" tabindex="-1">0.20.0-alt2 <a class="header-anchor" href="#_0-20-0-alt2" aria-label="Permalink to &quot;0.20.0-alt2&quot;">​</a></h2><p><strong>Дата выпуска</strong>: 08.04.2025 г.</p><ul><li>CMake получил своё обновление!</li></ul><h2 id="_0-20-0-alt1" tabindex="-1">0.20.0-alt1 <a class="header-anchor" href="#_0-20-0-alt1" aria-label="Permalink to &quot;0.20.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 17.03.2025</p><ul><li>Реализована поддержка LAPS 2023 (Local Administrator Password Solution).</li><li>Добавлена новая вкладка для объектов типа &quot;компьютер&quot;, где можно управлять LAPS-настройками.</li></ul><h2 id="_0-19-0-alt1" tabindex="-1">0.19.0-alt1 <a class="header-anchor" href="#_0-19-0-alt1" aria-label="Permalink to &quot;0.19.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 04.03.2025</p><p>Новое :</p><ul><li>Добавлено отображение дескриптора безопасности в формате SDDL через меню «More» на вкладке безопасности.</li><li>Добавлено действие Rollback к предыдущему дескриптору в меню «More».</li><li>Добавлено поле «Отчество» при создании пользователей (включается через настройки).</li><li>Добавлено действие «Копировать значение атрибута» .</li></ul><p>Исправления :</p><ul><li>Исправлено исчезновение необязательных атрибутов после нажатия «Сброс» во вкладке атрибутов.</li><li>Исправлено отображение msDS-User-Account-Control-Computed и msDS-User-Password-Expire-Time-Computed.</li><li>Уменьшены подтормаживания при работе с политиками в дереве.</li><li>Исправлены ошибки в changelog (Закрывает: <a href="https://bugzilla.altlinux.org/45839" target="_blank" rel="noreferrer">#45839</a>).</li></ul><h2 id="_0-18-0-alt1" tabindex="-1">0.18.0-alt1 <a class="header-anchor" href="#_0-18-0-alt1" aria-label="Permalink to &quot;0.18.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 05.12.2024</p><p>Новое :</p><ul><li>Добавлены настраиваемые разрешения во вкладку безопасности: создание/удаление дочерних объектов, чтение/запись свойств.</li><li>Добавлены задачи делегирования во вкладку безопасности — стандартные задачи из RSAT.</li><li>Расширенные права вынесены в отдельную вкладку.</li><li>Стандартные и общие разрешения теперь разделены и дополнены: просмотр содержимого, чтение/запись всех свойств, удаление, изменение владельца и др.</li><li>Добавлен выбор области применения разрешений: только текущий объект, объект и дочерние элементы, только дочерние или дочерние определённого класса.</li><li>Изменено поведение отключения прав: отключение родительского права приводит к отключению всех дочерних.</li><li>Добавлены действия &quot;Установить всё / Снять всё&quot; и &quot;Редактировать&quot; для вкладки связей политик в OU-виджете.</li></ul><p>Исправления :</p><ul><li>Исправлены тесты, падавшие из-за некорректного выбора контроллера домена.</li></ul><h2 id="_0-17-2-alt1" tabindex="-1">0.17.2-alt1 <a class="header-anchor" href="#_0-17-2-alt1" aria-label="Permalink to &quot;0.17.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 05.12.2024</p><p>Исправления :</p><ul><li>Исправлено отображение информации о сайтах и контроллерах домена для дочерних доменов (Закрывает: <a href="https://bugzilla.altlinux.org/52329" target="_blank" rel="noreferrer">#52329</a>).</li></ul><h2 id="_0-17-1-alt1" tabindex="-1">0.17.1-alt1 <a class="header-anchor" href="#_0-17-1-alt1" aria-label="Permalink to &quot;0.17.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 06.11.2024</p><p>Исправления :</p><ul><li>Исправлен краш при вызове контекстного меню на дочерних доменах.</li></ul><h2 id="_0-17-0-alt1" tabindex="-1">0.17.0-alt1 <a class="header-anchor" href="#_0-17-0-alt1" aria-label="Permalink to &quot;0.17.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 21.08.2024</p><p>Новое :</p><ul><li>Добавлено управление объектами политики паролей: создание, редактирование, удаление.</li><li>Контейнер с этими объектами расположен в папке System.</li><li>Добавлена возможность просмотра групп, в которые входит группа.</li></ul><p>Исправления :</p><ul><li>Исправлен вывод пустых скобок в виджете информации о домене при отсутствии версии контроллера.</li></ul><h2 id="_0-16-4-alt1" tabindex="-1">0.16.4-alt1 <a class="header-anchor" href="#_0-16-4-alt1" aria-label="Permalink to &quot;0.16.4-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 30.07.2024</p><p>Исправления :</p><ul><li>Обновлена совместимость с Samba 4.20, исправлены ошибки работы с дескрипторами безопасности (Закрывает: <a href="https://bugzilla.altlinux.org/50776" target="_blank" rel="noreferrer">#50776</a>).</li><li>Исправлено создание пользователей после обновления зависимостей Samba (Закрывает: <a href="https://bugzilla.altlinux.org/50096" target="_blank" rel="noreferrer">#50096</a>).</li></ul><h2 id="_0-16-3-alt1" tabindex="-1">0.16.3-alt1 <a class="header-anchor" href="#_0-16-3-alt1" aria-label="Permalink to &quot;0.16.3-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 15.05.2024</p><p>Исправления :</p><ul><li>Исправлены краши при попытках создания OU/пользователей у делегированных пользователей.</li></ul><h2 id="_0-16-2-alt1" tabindex="-1">0.16.2-alt1 <a class="header-anchor" href="#_0-16-2-alt1" aria-label="Permalink to &quot;0.16.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 03.05.2024</p><p>Исправления :</p><ul><li>Исправлен доступ к OU для пользователей с делегированием — теперь можно создавать/удалять пользователей, группы и политики в рамках своих прав.</li></ul><h2 id="_0-16-1-alt1" tabindex="-1">0.16.1-alt1 <a class="header-anchor" href="#_0-16-1-alt1" aria-label="Permalink to &quot;0.16.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 16.04.2024</p><p>Исправления :</p><ul><li>Исправлено удаление связей политик: после удаления связи из OU, она больше не остаётся в дереве (Закрывает: <a href="https://bugzilla.altlinux.org/49670" target="_blank" rel="noreferrer">#49670</a>).</li><li>Обновлены файлы бэкенда для совместимости с Samba 4.20.</li><li>Исправлен метод определения административного домена.</li><li>Исправлены краши при загрузке необязательных атрибутов.</li><li>Исправлены отображение и работа необязательных атрибутов при включённом LAPS.</li><li>Исправлены краши после применения изменений в свойствах доменных объектов.</li></ul><h2 id="_0-16-0-alt1" tabindex="-1">0.16.0-alt1 <a class="header-anchor" href="#_0-16-0-alt1" aria-label="Permalink to &quot;0.16.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 20.02.2024</p><p>Новое :</p><ul><li>Добавлена поддержка drag &amp; drop для изменения порядка политик.</li><li>Виджет информации о домене: удалены устаревшие элементы, добавлена версия контроллера домена.</li><li>Добавлены значки состояния политик (включено / отключено) на вкладке связей политик.</li><li>Исправлено удаление связей политик домена (ранее удалялись связи из других OU) (Закрывает: <a href="https://bugzilla.altlinux.org/49385" target="_blank" rel="noreferrer">#49385</a>).</li><li>Исправлено изменение значков политик после изменения состояния.</li><li>Исправлено дублирование ссылок в наследуемых политиках.</li><li>Исправлено изменение размера окна свойств пользователя.</li><li>Добавлена загрузка необязательных атрибутов через опцию в меню настроек или кнопку на вкладке атрибутов (Закрывает: <a href="https://bugzilla.altlinux.org/48817" target="_blank" rel="noreferrer">#48817</a>).</li><li>Исправлен выбор темы оформления при запуске ADMC.</li></ul><h2 id="_0-15-2-alt1" tabindex="-1">0.15.2-alt1 <a class="header-anchor" href="#_0-15-2-alt1" aria-label="Permalink to &quot;0.15.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 16.01.2024</p><p>Исправления :</p><ul><li>Удалено сообщение об ошибке при первом запуске, если тема отсутствует (Закрывает: <a href="https://bugzilla.altlinux.org/49043" target="_blank" rel="noreferrer">#49043</a>).</li></ul><h2 id="_0-15-1-alt1" tabindex="-1">0.15.1-alt1 <a class="header-anchor" href="#_0-15-1-alt1" aria-label="Permalink to &quot;0.15.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 13.12.2023</p><p>Новое :</p><ul><li>Добавлен выбор темы оформления: системные берутся из /usr/share/icons, пользовательские — из /usr/share/ad-integration. Темы должны содержать файл index.theme (или быть символическими ссылками).</li></ul><p>Исправления :</p><ul><li>Исправлены ошибки создания и отключения объектов из версии 0.15.0 (Закрывает: <a href="https://bugzilla.altlinux.org/48780" target="_blank" rel="noreferrer">#48780</a>).</li></ul><h2 id="_0-15-0-alt1" tabindex="-1">0.15.0-alt1 <a class="header-anchor" href="#_0-15-0-alt1" aria-label="Permalink to &quot;0.15.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 17.11.2023</p><p>Новое :</p><ul><li>Добавлен корневой элемент &quot;Домен&quot; в дерево консоли.</li><li>Виджет информации о домене показывает сайты, контроллеры, FSMO-роли, уровни функциональности, номер схемы.</li></ul><p>Исправления :</p><ul><li>Исправлена работа с сохранением параметров подключения после неудачной попытки.</li><li>Исправлено создание и переименование GPO с пробелами (Закрывает: <a href="https://bugzilla.altlinux.org/44684" target="_blank" rel="noreferrer">#44684</a>).</li><li>Добавлен автоподбор samAccountName при переименовании группы (Закрывает: <a href="https://bugzilla.altlinux.org/47082" target="_blank" rel="noreferrer">#47082</a>).</li><li>Добавлена иконка отключенного компьютера (Закрывает: <a href="https://bugzilla.altlinux.org/47551" target="_blank" rel="noreferrer">#47551</a>).</li><li>Добавлено предупреждение при удалении нескольких объектов и непустых OU.</li></ul><h2 id="_0-14-0-alt1" tabindex="-1">0.14.0-alt1 <a class="header-anchor" href="#_0-14-0-alt1" aria-label="Permalink to &quot;0.14.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 05.09.2023</p><p>Исправления :</p><ul><li>Исправлены ошибки, возникающие при переключении контроллеров домена (обнаружены через упавшие тесты).</li><li>Добавлена иконка отключённого пользователя в менеджере иконок.</li><li>Обновлён механизм проверки прав администратора: теперь для добавления GPO не обязательно быть в группе &quot;Domain Admins&quot; — используется проверка по SID.</li><li>Исправлено исчезновение ссылок на политики после применения действий &quot;Enforce&quot;/&quot;Disable&quot; через контекстное меню (Закрывает: <a href="https://bugzilla.altlinux.org/47122" target="_blank" rel="noreferrer">#47122</a>).</li><li>Исправлен тест admc_test_gplink.</li><li>Временно удалён тест admc_test_policy_ou_results_widget.</li></ul><p>Новое :</p><ul><li>Добавлена возможность подключения к хосту другого домена.</li></ul><h2 id="_0-13-0-alt1" tabindex="-1">0.13.0-alt1 <a class="header-anchor" href="#_0-13-0-alt1" aria-label="Permalink to &quot;0.13.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 17.07.2023</p><p>Новое :</p><ul><li>Добавлена опция проверки PDC-эмулятора. При её активации запрещено редактирование/удаление политик, если соединение - установлено не с PDC-эмулятором.</li><li>Добавлены наследуемые политики во вкладку организационных единиц.</li><li>Контекстное меню элементов политик теперь содержит действия «Принудительно» и «Отключить».</li><li>Добавлены виджеты только для чтения на вкладке «Общие сведения» для пользователей и групп.</li><li>Реализовано отображение атрибутов userAccountControl, msDs-Supported и systemFlags в шестнадцатеричном формате.</li></ul><p>Исправления :</p><ul><li>Исправлена сортировка порядка политик в OU: раньше сортировка воспринимала номер как строку, теперь — как число.</li><li>Исправлены кнопки OK при переименовании OU и пользователей, если имя состояло только из пробелов.</li><li>Устранён краш при попытке drag &amp; drop в OU-виджете.</li><li>Исправлено отображение значения атрибута creationTime.</li><li>Добавлено отображение и редактирование временных атрибутов (forceLogoff, lockOutObservationWindow).</li><li>Исправлено отображение политики после несанкционированного добавления.</li></ul><h2 id="_0-12-0-alt1" tabindex="-1">0.12.0-alt1 <a class="header-anchor" href="#_0-12-0-alt1" aria-label="Permalink to &quot;0.12.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 22.03.2023</p><p>Новое :</p><ul><li>Добавлен индикатор блокировки наследования на иконку OU.</li><li>Добавлен индикатор принудительной связи на иконку политики.</li><li>Изменён внешний вид отключённых политик (иконка затеняется).</li><li>Добавлен индикатор ссылки на политику в левом нижнем углу иконки.</li><li>Политики, связанные с доменом, теперь отображаются в списке политик.</li><li>Порядок отображения политик изменён — они теперь выше OU.</li></ul><p>Исправления :</p><ul><li>Уменьшены отступы в OU-виджете с политиками.</li><li>Добавлен эллипсис («…») для длинных имён в панели описания.</li><li>Информация о полном имени объекта отображается в tooltip.</li><li>Отображение и редактирование атрибута groupType переведено из десятичного в шестнадцатеричный формат с отображением флагов.</li><li>Удалены диалоговые окна ошибок при выборе критических политик — сообщения теперь выводятся в лог.</li><li>Сообщения об ошибках при удалении политик уточнены.</li><li>Логи на русском языке больше не появляются в английской версии и наоборот.</li></ul><h2 id="_0-11-2-alt1" tabindex="-1">0.11.2-alt1 <a class="header-anchor" href="#_0-11-2-alt1" aria-label="Permalink to &quot;0.11.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 10.01.2023</p><p>Исправления :</p><ul><li>Исправлены гонки (race condition) с интерфейсом AdInterface.</li></ul><h2 id="_0-11-1-alt1" tabindex="-1">0.11.1-alt1 <a class="header-anchor" href="#_0-11-1-alt1" aria-label="Permalink to &quot;0.11.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 10.01.2023</p><p>Исправления :</p><ul><li>Улучшена визуализация вкладок свойств.</li><li>Добавлена возможность использовать атрибуты пользователя и компьютера при создании GPO.</li><li>Исправлена доступность кнопки OK: <ul><li>при отсутствии названия политики в диалоге создания;</li><li>при отсутствии имени группы в диалоге переименования OU;</li><li>при отсутствии имени пользователя в диалоге переименования.</li></ul></li></ul><h2 id="_0-11-0-alt1" tabindex="-1">0.11.0-alt1 <a class="header-anchor" href="#_0-11-0-alt1" aria-label="Permalink to &quot;0.11.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 13.12.2022</p><p>Новое :</p><ul><li>Добавлена функция «Блокировать наследование» в контекстное меню OU.</li></ul><p>Исправления :</p><ul><li>Исправлен краш при работе с пустыми объектами политик.</li><li>Неудаляемые контейнеры политик больше не исчезают из GUI — вместо этого показывается предупреждение.</li><li>Добавлена колонка «Порядок» в OU-виджет политик; используется по умолчанию для сортировки.</li><li>Исправлен краш в дереве политик после изменения свойств OU.</li><li>Исправлено сжатие области просмотра из-за длинного имени выбранного элемента.</li><li>Иконки создания OU, пользователей и групп в тулбаре исправлены.</li><li>Добавлено удаление лишних пробелов при автозаполнении полного имени.</li><li>Добавлено удаление лишних пробелов при редактировании sAMAccountName в диалоге создания компьютеров.</li><li>Добавлено действие «Найти GPO» в дерево политик — реализует поиск политик.</li><li>Улучшено действие «Импорт запроса» — теперь можно импортировать несколько запросов за раз.</li></ul><h2 id="_0-10-0-alt3" tabindex="-1">0.10.0-alt3 <a class="header-anchor" href="#_0-10-0-alt3" aria-label="Permalink to &quot;0.10.0-alt3&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 12.09.2022</p><p>Улучшения :</p><ul><li>Очищены зависимости Requires и BuildRequires.</li></ul><h2 id="_0-10-0-alt2" tabindex="-1">0.10.0-alt2 <a class="header-anchor" href="#_0-10-0-alt2" aria-label="Permalink to &quot;0.10.0-alt2&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 07.09.2022</p><p>Новое :</p><ul><li>Собран последний протестированный релиз.</li></ul><p>Улучшения :</p><ul><li>Обновлено описание пакета (Summary, Description).</li></ul><h2 id="_0-10-0-alt1" tabindex="-1">0.10.0-alt1 <a class="header-anchor" href="#_0-10-0-alt1" aria-label="Permalink to &quot;0.10.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 30.06.2022</p><p>Изменения :</p><ul><li>Удалена вкладка «Группы» — заменена на древовидное представление политик.</li></ul><p>Новое :</p><ul><li>Политики и OU объединены в одном дереве. OU отображает свои дочерние OU и связанные политики.</li><li>Все политики остаются доступными в разделе «Все политики».</li></ul><p>Исправления :</p><ul><li>Исправлено отображение длинных элементов в Scope View — добавлен скроллбар.</li><li>Добавлено автоматическое удаление лишних пробелов при создании или переименовании политик, папок и элементов запросов.</li><li>Исправлен баг, при котором объект выгружался при добавлении символа «?» в его имя.</li><li>Увеличен размер поля редактирования строковых атрибутов на вкладке «Атрибуты».</li><li>Запрещено перетаскивание политик на OU в дереве объектов — это действие теперь доступно внутри дерева политик.</li></ul><h2 id="_0-9-0-alt1" tabindex="-1">0.9.0-alt1 <a class="header-anchor" href="#_0-9-0-alt1" aria-label="Permalink to &quot;0.9.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 01.04.2022</p><ul><li>Обновление до версии 0.9.0 (подробности см. в CHANGELOG.txt).</li></ul><h2 id="_0-8-3-alt1" tabindex="-1">0.8.3-alt1 <a class="header-anchor" href="#_0-8-3-alt1" aria-label="Permalink to &quot;0.8.3-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 31.03.2022</p><p>Версия: 0.8.3 (подробности см. в CHANGELOG.txt).</p><ul><li>Удалена автоматически генерируемая запись о changelog из .spec файла.</li></ul><h2 id="_0-6-4-alt1" tabindex="-1">0.6.4-alt1 <a class="header-anchor" href="#_0-6-4-alt1" aria-label="Permalink to &quot;0.6.4-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 05.08.2021</p><p>Версия: 0.6.4</p><p>Исправления:</p><ul><li>Закрыты баги: <a href="https://bugzilla.altlinux.org/40653" target="_blank" rel="noreferrer">#40653</a>, <a href="https://bugzilla.altlinux.org/40654" target="_blank" rel="noreferrer">#40654</a></li></ul><h2 id="_0-6-3-alt1" tabindex="-1">0.6.3-alt1 <a class="header-anchor" href="#_0-6-3-alt1" aria-label="Permalink to &quot;0.6.3-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 02.08.2021</p><p>Версия: 0.6.3</p><h2 id="_0-6-2-alt1" tabindex="-1">0.6.2-alt1 <a class="header-anchor" href="#_0-6-2-alt1" aria-label="Permalink to &quot;0.6.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 29.07.2021</p><p>Версия: 0.6.2</p><p>Исправления:</p><ul><li>Закрыта бага: <a href="https://bugzilla.altlinux.org/40562" target="_blank" rel="noreferrer">#40562</a></li></ul><h2 id="_0-6-1-alt1" tabindex="-1">0.6.1-alt1 <a class="header-anchor" href="#_0-6-1-alt1" aria-label="Permalink to &quot;0.6.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 20.07.2021</p><p>Версия: 0.6.1</p><h2 id="_0-6-0-alt1" tabindex="-1">0.6.0-alt1 <a class="header-anchor" href="#_0-6-0-alt1" aria-label="Permalink to &quot;0.6.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 09.07.2021</p><p>Версия: 0.6.0</p><h2 id="_0-5-3-alt1" tabindex="-1">0.5.3-alt1 <a class="header-anchor" href="#_0-5-3-alt1" aria-label="Permalink to &quot;0.5.3-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 21.06.2021</p><p>Версия: 0.5.3</p><h2 id="_0-5-2-alt1-1" tabindex="-1">0.5.2-alt1.1 <a class="header-anchor" href="#_0-5-2-alt1-1" aria-label="Permalink to &quot;0.5.2-alt1.1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 30.05.2021</p><p>Версия: 0.5.2</p><p>Обновления:</p><ul><li>NMU: адаптация .spec под новые макросы CMake.</li></ul><h2 id="_0-5-2-alt1" tabindex="-1">0.5.2-alt1 <a class="header-anchor" href="#_0-5-2-alt1" aria-label="Permalink to &quot;0.5.2-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 12.05.2021</p><p>Версия: 0.5.2</p><h2 id="_0-5-1-alt1" tabindex="-1">0.5.1-alt1 <a class="header-anchor" href="#_0-5-1-alt1" aria-label="Permalink to &quot;0.5.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 23.04.2021</p><p>Версия: 0.5.1</p><h2 id="_0-5-0-alt1" tabindex="-1">0.5.0-alt1 <a class="header-anchor" href="#_0-5-0-alt1" aria-label="Permalink to &quot;0.5.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 22.04.2021</p><p>Версия: 0.5.0</p><h2 id="_0-4-1-alt1" tabindex="-1">0.4.1-alt1 <a class="header-anchor" href="#_0-4-1-alt1" aria-label="Permalink to &quot;0.4.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 02.03.2021</p><p>Версия: 0.4.1</p><h2 id="_0-4-0-alt1" tabindex="-1">0.4.0-alt1 <a class="header-anchor" href="#_0-4-0-alt1" aria-label="Permalink to &quot;0.4.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 15.02.2021</p><p>Версия: 0.4.0</p><h2 id="_0-3-1-alt2" tabindex="-1">0.3.1-alt2 <a class="header-anchor" href="#_0-3-1-alt2" aria-label="Permalink to &quot;0.3.1-alt2&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 27.12.2020</p><p>Версия: 0.3.1</p><p>Изменения:</p><ul><li>Удалён пакет openldap из зависимостей Requires.</li></ul><h2 id="_0-3-1-alt1" tabindex="-1">0.3.1-alt1 <a class="header-anchor" href="#_0-3-1-alt1" aria-label="Permalink to &quot;0.3.1-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 28.07.2020</p><p>Версия: 0.3.1</p><p>Исправления:</p><ul><li>Исправлено закрытие приложения при закрытии диалога входа.</li><li>Исправлены сегфолты при чтении атрибутов в формате BER.</li></ul><h2 id="_0-3-0-alt1" tabindex="-1">0.3.0-alt1 <a class="header-anchor" href="#_0-3-0-alt1" aria-label="Permalink to &quot;0.3.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 24.07.2020</p><p>Версия: 0.3.0</p><p>Новое:</p><ul><li>Поддержка сборки ADMC для всех архитектур.</li></ul><h2 id="_0-2-0-alt1" tabindex="-1">0.2.0-alt1 <a class="header-anchor" href="#_0-2-0-alt1" aria-label="Permalink to &quot;0.2.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 24.07.2020</p><p>Версия: 0.2.0</p><p>Новое:</p><ul><li>Добавлены переводы интерфейса.</li><li>Реализован диалог входа.</li><li>Улучшена библиотека libadldap.</li><li>Внесены различные улучшения пользовательского интерфейса.</li></ul><h2 id="_0-1-0-alt1" tabindex="-1">0.1.0-alt1 <a class="header-anchor" href="#_0-1-0-alt1" aria-label="Permalink to &quot;0.1.0-alt1&quot;">​</a></h2><p><strong>Дата выпуска</strong> : 21.05.2020</p><p>Версия: 0.1.0</p><p>Первая сборка проекта.</p>',192)]))}const c=a(e,[["render",o]]);export{g as __pageData,c as default};
